const TRAINING=[
{number:'01',title:'Propósito: por que fazemos mídia',lead:'Antes de falar de câmera, de stories e de reels, vamos falar de coração. Quem grava, edita, fotografa e posta também serve para que a Palavra alcance pessoas. Estamos aqui para o Senhor. Nosso alvo é servir com fidelidade, atenção e amor.',items:[
['Olhar um para o outro','Equipe é um corpo. Se um membro brilha, todos brilham juntos. Ninguém carrega o peso sozinho. Terminou sua parte? Olhe ao lado e pergunte quem ainda precisa de ajuda. Compartilhe conhecimento e celebre as entregas do outro.'],
['Motivação, não posição','Estamos sendo treinados para servir bem, com excelência, onde formos colocados. Cargo não é o alvo: fidelidade é. Uma tarefa pequena, feita com amor, também honra o Senhor. Tenha um coração disponível para colaborar além da sua área.'],
['Compromisso é palavra dada','Ao dizer “sim”, você assume um compromisso com sua palavra, com o time e com o Senhor. Chegue no horário, entregue o combinado no tempo combinado e faça o seu melhor. Se surgir um imprevisto, avise a liderança com antecedência.'],
['Organização também faz parte do serviço','Saiba o que entregar, quando entregar e quem é responsável. Uma equipe organizada evita atrasos e sobrecarga. Consulte sua escala, confira os checks e comunique o andamento. Pedir ajuda cedo faz parte da responsabilidade.'],
['Servir fortalece a igreja local','A escola passa; nossa vida de serviço continua na igreja local. Aqui aprendemos a caminhar como corpo, a honrar a liderança e a cuidar das pessoas. Leve essa disposição para sua comunidade: presença, compromisso e amor também fora dos dias da CALL.']
]},
{number:'1B',title:'Adoradores que servem',lead:'Teremos dias intensos e imprevistos. Nossa entrega precisa de consagração, sensibilidade e cuidado. Somos voluntários: aprendemos juntos, dividimos o trabalho e avisamos quando precisamos de apoio para servir bem.',items:[
['Primeiro adoradores, depois equipe','Viva o culto de verdade: adore, ore e dê lugar ao Espírito. Lembre também da demanda confiada a você naquele momento. Se precisar se afastar da cobertura, alinhe com alguém para que o momento continue sendo registrado. Adoração e serviço caminham juntos.'],
['Consagração e organização','Espontaneidade não dispensa preparo. Fotografar, gravar, editar e publicar pedem dedicação: nossa entrega pode levar a Palavra e os testemunhos a quem não esteve ali. Prepare seus recursos e conheça sua função antes de começar.'],
['Sensibilidade para registrar','Antes de cada bloco, ore: “Senhor, me dá sensibilidade para saber o que registrar.” Observe o ambiente e saiba quando captar e quando simplesmente estar presente. Mova-se com discrição, respeite quem está orando e preserve momentos íntimos.'],
['A postura dos bastidores também é testemunho','Mansidão, humildade e paciência devem marcar nossas conversas. Seja gentil quando alguém errar ou um equipamento falhar. Respeite alunos, tutores e pessoas que estejam chorando ou recebendo oração. Cuide do ambiente também com suas atitudes.'],
['Proatividade e fluxo','Viu uma bateria acabando? Avise. Viu um ângulo sem cobertura? Combine com o time e ajude. Terminou sua parte? Pergunte quem precisa de apoio. Observe o que precisa ser feito e mantenha a equipe informada.'],
['Cuidado com os equipamentos','Confira as cargas na noite anterior. Antes de cada culto ou aula, faça com a equipe uma checagem de bateria, espaço no cartão e áudio. Guarde cabos, tripés e microfones no lugar combinado. Zele pelo material e avise imediatamente se houver um problema.'],
['Proteja os arquivos e o trabalho do time','Ao fim de cada bloco grande, descarregue os cartões e confira o backup. Verifique se os arquivos abrem e estão completos antes de apagar ou formatar o cartão. Organize brutos e editados nas pastas combinadas para que a próxima pessoa encontre tudo.']
]},
{number:'1C',title:'Testemunho, postura e convivência',lead:'Nosso testemunho aparece dentro e fora da CALL. Somos uma equipe da igreja, cuidando de pessoas. Unidade, empatia e humildade precisam estar presentes no que publicamos e na forma como convivemos.',items:[
['Buscar a paz com todos','Mesmo com cansaço, pressa e imprevistos, busque a paz com a equipe, os tutores e a organização. Converse com respeito, escute antes de responder e procure resolver as dificuldades com mansidão.'],
['Somos uma ponte para os alunos','Sorria, seja solícito e esteja disponível. Ajude mesmo quando a necessidade não for da sua área. Fazer parte da mídia não nos coloca acima de ninguém: estamos aqui para servir junto com toda a escola. No fim, somos um só.'],
['Unidade também na apresentação','Siga o padrão de vestimenta combinado pela equipe e pela organização. Prepare sua roupa com antecedência e mantenha uma postura adequada aos ambientes em que vai servir.'],
['Submissão e respeito mútuo','Honre as orientações dos líderes e da diretoria. Caminhe também em respeito aos irmãos que servem com você: ouça, ajuste quando necessário e coopere. Nossa unidade vale mais que uma preferência individual.'],
['Comunicação direta, cuidado real','Qualquer problema ou dificuldade deve chegar à coordenação. Evite deixar a situação apenas em comentários entre colegas. Procure Sarah para alinhar e buscar solução. Assim como há pessoas cuidando de nós, também estamos aqui para cuidar de outras pessoas.']
]}
];
function renderTraining(){return `<section id="servir" class="training-section"><div class="eyebrow">TREINAMENTO DA EQUIPE DE MÍDIA / CALL 16:15</div><h2>Antes da lente,<br>um coração disponível.</h2><p class="training-lead">Escola de Evangelismo e Missões · Nosso serviço nasce do amor ao Senhor e às pessoas. Quando um brilha, todos brilham. Quando um precisa de ajuda, ninguém fica sozinho.</p><nav class="training-nav" aria-label="Módulos do treinamento">${TRAINING.map((m,i)=>`<a href="#modulo-${i}">${m.number} · ${m.title}</a>`).join('')}</nav>${TRAINING.map((m,i)=>`<article class="training-module" id="modulo-${i}"><div class="eyebrow">MÓDULO ${m.number}</div><h3>${m.title}</h3><p>${m.lead}</p><div class="training-grid">${m.items.map((x,j)=>`<div class="training-item"><span>${String(j+1).padStart(2,'0')}</span><h4>${x[0]}</h4><p>${x[1]}</p></div>`).join('')}</div></article>`).join('')}<div class="training-close">Um time que cuida das pessoas também cuida uns dos outros.<br><strong>Sirva com alegria. Peça ajuda. Ofereça ajuda.</strong></div></section>`}
